// Fila a agregar según la pestaña (?pestana=Registro|Comidas|Agua y los datos).
const q = $json.query || {};
const ahora = $now.setZone('America/Argentina/Buenos_Aires');
const f = ahora.toFormat('dd/MM/yyyy'), h = ahora.toFormat('HH:mm');
const n = v => { const x = parseFloat(String(v ?? '').replace(',', '.')); return isNaN(x) ? 0 : x; };
const p = String(q.pestana || '').toLowerCase();
let rango, fila, para;
if (p.startsWith('comida')) { rango = 'Comidas!A:G'; para = 'comidas'; fila = [f, h, q.comida || '', n(q.kcal), n(q.proteina), n(q.carbos), n(q.grasas)]; }
else if (p.startsWith('agua')) { rango = 'Agua!A:D'; para = 'comidas'; fila = [f, h, n(q.ml), q.que || 'agua']; }
else { rango = 'Registro!A:G'; para = 'gimnasio'; fila = [f, q.dia || '', q.ejercicio || '', n(q.peso), n(q.series), String(q.repeticiones || ''), q.notas || '']; }
return [{ json: { rango, fila, para, ejercicio: q.ejercicio || '' } }];

// Una línea para JARVIS con lo que lleva hoy (así no tiene que pedir el resumen aparte).
const pr = $('Preparar').first().json;
const p = $json;
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
let t = 'Anotado. ';
if (pr.para === 'comidas') {
  const c = p.comidas, a = p.agua;
  t += `Hoy llevás ${c.total.kcal} de ${c.objetivo.kcal} kcal; proteína ${c.total.p}/${c.objetivo.p} g, carbos ${c.total.c}/${c.objetivo.c} g, grasas ${c.total.g}/${c.objetivo.g} g; agua ${a.total}/${a.objetivo} ml.`;
} else {
  const e = (p.proximas || []).find(x => norm(x.ejercicio).includes(norm(pr.ejercicio)) || norm(pr.ejercicio).includes(norm(x.ejercicio).split(' o ')[0]));
  if (e) t += `La proxima vez en ${e.ejercicio}: ${e.proxima}.`;
}
return [{ json: { texto: t } }];
